parameters.jsCode:
// Validate leave request
const leave = $input.first().json.body || $input.first().json;

// Required fields
const required = ['employee_id', 'employee_name', 'employee_email', 'manager_email', 'start_date', 'end_date', 'leave_type'];
const missing = required.filter(field => !leave[field]);

if (missing.length > 0) {
  throw new Error(`Missing fields: ${missing.join(', ')}`);
}

// Vietnamese leave types
const validLeaveTypes = [
  'annual_leave',      // Phép năm
  'unpaid_leave',      // Phép không lương
  'sick_leave',        // Ốm
  'maternity_leave',   // Thai sản
  'bereavement_leave', // Tang chế
  'personal_leave',    // Việc riêng
  'training_leave'     // Đào tạo
];

if (!validLeaveTypes.includes(leave.leave_type)) {
  throw new Error(`Invalid leave type. Must be one of: ${validLeaveTypes.join(', ')}`);
}

// Parse and validate dates
const startDate = new Date(leave.start_date);
const endDate = new Date(leave.end_date);
const today = new Date();
today.setHours(0, 0, 0, 0);

if (isNaN(startDate.getTime()) || isNaN(endDate.getTime())) {
  throw new Error('Invalid date format');
}

if (startDate < today) {
  throw new Error('Start date cannot be in the past');
}

if (endDate < startDate) {
  throw new Error('End date cannot be before start date');
}

// Calculate leave days (excluding weekends)
let leaveDays = 0;
let currentDate = new Date(startDate);
while (currentDate <= endDate) {
  const dayOfWeek = currentDate.getDay();
  if (dayOfWeek !== 0 && dayOfWeek !== 6) { // Exclude weekends
    leaveDays++;
  }
  currentDate.setDate(currentDate.getDate() + 1);
}

// Vietnamese leave type labels
const leaveTypeLabels = {
  annual_leave: 'Phép năm',
  unpaid_leave: 'Phép không lương',
  sick_leave: 'Ốm',
  maternity_leave: 'Thai sản',
  bereavement_leave: 'Tang chế',
  personal_leave: 'Việc riêng',
  training_leave: 'Đào tạo'
};

const sanitized = {
  employee_id: leave.employee_id.trim(),
  employee_name: leave.employee_name.trim(),
  employee_email: leave.employee_email.toLowerCase().trim(),
  manager_email: leave.manager_email.toLowerCase().trim(),
  start_date: leave.start_date,
  end_date: leave.end_date,
  start_date_formatted: startDate.toLocaleDateString('vi-VN'),
  end_date_formatted: endDate.toLocaleDateString('vi-VN'),
  leave_type: leave.leave_type,
  leave_type_label: leaveTypeLabels[leave.leave_type],
  reason: leave.reason?.trim() || 'Không có lý do',
  leave_days: leaveDays,
  status: 'pending',
  request_id: `LEAVE-${Date.now()}`,
  created_at: new Date().toISOString(),
  timezone: 'Asia/Ho_Chi_Minh'
};

return [{ json: sanitized }];

// Check leave balance and overlapping requests
const leave = $input.first().json;
const balance = $('Get Leave Balance (Google Sheets)').first().json || {};

// Get remaining balance for leave type
const balanceField = leave.leave_type;
const remainingBalance = parseFloat(balance[balanceField]) || 0;

// Check if sufficient balance
const hasBalance = remainingBalance >= leave.leave_days;

// Check for overlapping leaves
const existingLeaves = $('Get Leave Balance (Google Sheets)').all()
  .map(item => item.json)
  .filter(item => item.employee_id === leave.employee_id && item.status === 'approved');

let hasOverlap = false;
for (const existing of existingLeaves) {
  const existingStart = new Date(existing.start_date);
  const existingEnd = new Date(existing.end_date);
  const newStart = new Date(leave.start_date);
  const newEnd = new Date(leave.end_date);

  if (newStart <= existingEnd && newEnd >= existingStart) {
    hasOverlap = true;
    break;
  }
}

const remainingAfter = hasBalance ? remainingBalance - leave.leave_days : remainingBalance;

return [{
  json: {
    ...leave,
    remaining_balance: remainingBalance,
    remaining_after: remainingAfter,
    has_balance: hasBalance,
    has_overlap: hasOverlap,
    validation_passed: hasBalance && !hasOverlap,
    rejection_reason: !hasBalance ? 'Không đủ số ngày phép' : 
                      hasOverlap ? 'Trùng với đơn nghỉ phép đã được duyệt' : null
  }
}];

